"use client"
import {FormEvent,useEffect,useState} from "react";
import Wrapper from "@/layouts/Wrapper";
import DashboardHeaderTwo from "@/layouts/headers/dashboard/DashboardHeaderTwo";
import {createClient} from "@/lib/supabase/client";

type Vendor={id:string;name:string;category:string;phone:string|null;email:string|null;document:string|null;notes:string|null};
export default function VendorsPage(){
 const supabase=createClient();const [items,setItems]=useState<Vendor[]>([]);const [form,setForm]=useState({name:"",category:"general",phone:"",email:"",document:"",notes:""});const [msg,setMsg]=useState("");
 async function load(){const {data,error}=await supabase.from("vendors").select("*").order("name");if(error)setMsg(error.message);else setItems((data??[]) as Vendor[])}
 useEffect(()=>{load()},[]);
 async function save(e:FormEvent){e.preventDefault();const {data:{user}}=await supabase.auth.getUser();if(!user)return;const {error}=await supabase.from("vendors").insert({user_id:user.id,name:form.name.trim(),category:form.category,phone:form.phone.trim()||null,email:form.email.trim()||null,document:form.document.trim()||null,notes:form.notes.trim()||null});if(error)setMsg(error.message);else{setForm({name:"",category:"general",phone:"",email:"",document:"",notes:""});await load()}}
 return <Wrapper><div className="dashboard-body"><DashboardHeaderTwo title="Fornecedores"/><h2 className="main-title mb-1">Fornecedores</h2><p className="mb-25">Prestadores e parceiros vinculáveis à operação imobiliária.</p>
 <form onSubmit={save}><div className="bg-white card-box border-20 mb-30"><div className="row"><div className="col-md-5"><div className="dash-input-wrapper mb-25"><label>Nome*</label><input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></div></div><div className="col-md-3"><div className="dash-input-wrapper mb-25"><label>Categoria</label><select className="nice-select" value={form.category} onChange={e=>setForm({...form,category:e.target.value})}><option value="general">Geral</option><option value="plumbing">Hidráulica</option><option value="electrical">Elétrica</option><option value="painting">Pintura</option><option value="legal">Jurídico</option><option value="accounting">Contábil</option></select></div></div><div className="col-md-4"><div className="dash-input-wrapper mb-25"><label>CPF/CNPJ</label><input value={form.document} onChange={e=>setForm({...form,document:e.target.value})}/></div></div><div className="col-md-4"><div className="dash-input-wrapper mb-25"><label>Telefone</label><input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></div></div><div className="col-md-4"><div className="dash-input-wrapper mb-25"><label>E-mail</label><input value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></div></div><div className="col-md-4"><div className="dash-input-wrapper mb-25"><label>Observações</label><input value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></div></div></div>{msg&&<p>{msg}</p>}<button className="dash-btn-two tran3s">Salvar fornecedor</button></div></form>
 <div className="bg-white card-box border-20"><div className="table-responsive"><table className="table"><thead><tr><th>Nome</th><th>Categoria</th><th>Contato</th><th>Documento</th></tr></thead><tbody>{items.length?items.map(v=><tr key={v.id}><td><strong>{v.name}</strong></td><td>{v.category}</td><td>{v.phone||v.email||"—"}</td><td>{v.document||"—"}</td></tr>):<tr><td colSpan={4} className="text-center py-5">Nenhum fornecedor cadastrado.</td></tr>}</tbody></table></div></div>
 </div></Wrapper>
}